/** Full Arabic native service guide, with explicit regional legal cautions. */
internal object FooterArabic175Guide {
    val sections: Map<String, Pair<String, String>> = mapOf(
        "What is BetVima?" to ("ما هي BetVima؟" to "تجمع BetVima واجهات الرياضة والأحداث المباشرة والكازينو والحساب والمحفظة والدعم تحت علامة واحدة. تعتمد بيانات الرياضة وأسواق الرهان على المزوّد والخادم، ولا تعني مشاهدة المباراة أو السوق توفر رهان معتمد. يختلف توفر الخدمات باختلاف البلد والأهلية والقانون المحلي."),
        "Create an account and secure it" to ("إنشاء الحساب وتأمينه" to "ابدأ بتسجيل بيانات صحيحة واختر عملة الحساب بعناية. احتفظ بكلمة المرور ورموز الاسترداد بصورة خاصة، واستخدم المصادقة الثنائية حيث تتوفر. تحقّق من رسائل الخادم عند تأكيد التسجيل أو تعديل بياناتك، ولا تعتبر إعدادات PIN المحلية بديلًا عن حماية الحساب من الخادم."),
        "Find sports, leagues and events" to ("العثور على الرياضات والدوريات والمباريات" to "تصفح الرياضات والبطولات والمباريات المباشرة والقادمة أو استخدم البحث والفلاتر. تعتمد القوائم على المباريات التي يعرضها المزوّد فعليًا؛ وقد تختلف التغطية والبيانات المباشرة والأسواق من دوري إلى آخر. حدّث الصفحة عندما تنقطع البيانات وتحقق من حالة السوق قبل الاختيار."),
        "How to place a single bet" to ("كيفية وضع رهان فردي" to "اختر مباراة وسوقًا متاحًا ثم نتيجة واحدة وأضفها إلى قسيمة الرهان. أدخل المبلغ المناسب لعملة حسابك، ثم راجع الحد الأدنى والاحتمالات والعائد المتوقع. يجب أن يقبل الخادم الرهان ويصدر تأكيدًا رسميًا. إن تغير السعر، راجع الاحتمال الجديد ووافق عليه قبل إعادة الإرسال."),
        "Multiple bets and bet history" to ("الرهانات المركبة وسجل الرهانات" to "يمكن جمع اختيارات مسموحة في رهان مركب وفق قواعد توافق الأسواق. يختلف حساب العائد بحسب الاحتمالات المقبولة وحالة كل اختيار. افتح «رهاناتي» لمتابعة الرهانات المفتوحة والمحسومة والفائزة والخاسرة والملغاة وتصحيحات النتائج. لا ترسل الرهان مرة ثانية إن كانت حالته غير مؤكدة قبل مراجعة السجل."),
        "Understand wallet balances" to ("فهم أرصدة المحفظة" to "تُظهر المحفظة الرصيد المتاح والإجمالي والمحجوز، وقد تكون بعض المبالغ معلقة بانتظار تسوية أو تأكيد مزوّد الدفع. يعتمد الرصيد المالي على سجل الخادم، وليس على تحديثات الشاشة وحدها. راجع سجل المعاملات قبل اتخاذ أي قرار مالي."),
        "Cryptocurrency deposits" to ("الإيداع بالعملات المشفرة" to "اختر الأصل الرقمي والشبكة المدعومين من واجهة الدفع الرسمية، ثم انسخ عنوان الإيداع الذي يعرضه الخادم. تحقق من تطابق الشبكة والعنوان قبل الإرسال، ولا تحول الأموال إلى عنوان مفترض. قد يتأخر إظهار الإيداع حتى استلام التأكيدات اللازمة من المزوّد."),
        "Crypto withdrawal and settlement" to ("سحب العملات المشفرة وتسويتها" to "احفظ عنوان محفظة الوجهة للشبكة المناسبة وتحقق منه بدقة. راجع الرصيد المتاح والحدود الدنيا والرسوم وتفاصيل الطلب قبل الموافقة. قد يبقى السحب قيد المراجعة أو المعالجة حتى تؤكد الجهة المسؤولة الدفع. إرسال طلب السحب لا يعادل اكتمال التحويل."),
        "U-Voucher and HotVoucher deposits" to ("الإيداع عبر U-Voucher وHotVoucher" to "عند توفر طريقة القسيمة، اخترها وأدخل الرمز الصحيح واتبع تعليمات النظام والمزوّد. راجع عملة الحساب والقيمة والحدود المعلنة؛ قد تختلف قيمة التسوية عن القيمة الاسمية للقسيمة بسبب قواعد التحويل. لا تشارك رمز القسيمة مع أشخاص غير موثوقين."),
        "U-Voucher and HotVoucher withdrawals" to ("السحب عبر U-Voucher وHotVoucher" to "إذا كانت خدمة السحب بالقسيمة متاحة على حسابك، حدد الطريقة وأكمل البيانات المطلوبة وتحقق من الحد الأدنى وسعر التحويل الحالي. لا تعتبر القسيمة صادرة حتى يؤكد الخادم نجاح العملية. راجع السجل وحالة الدفع في حال التأخير بدل تكرار الطلب."),
        "Account currency, exchange rates and fees" to ("عملة الحساب وأسعار الصرف والرسوم" to "تدعم واجهة المحفظة الدولار الأمريكي والريال الإيراني وفق إعداد حسابك. قد تعرض المدفوعات قيمًا مقوّمة بعملة أخرى حسب مزوّد الدفع. أسعار الصرف والحدود والرسوم يمكن أن تتغير؛ تحقق من السعر الفعلي الذي يؤكده الخادم وقت الإرسال. لا تفترض أن القيمة المعروضة تقديريًا هي مبلغ التسوية النهائي."),
        "Using BetVima from Iran" to ("استخدام BetVima من إيران" to "تختلف قواعد المراهنة والمدفوعات والإنترنت بحسب الموقع والقوانين السارية. توفر لغة فارسية أو إمكانية فتح التطبيق لا يعني قانونية الخدمة في إيران أو ضمان إتاحتها. تحقق من المتطلبات المحلية وشروط مزوّدي الدفع ولا تحاول تجاوز قيود قانونية. لا يتحول اختيار الريال الإيراني إلى إثبات للأهلية."),
        "Using BetVima from Turkey" to ("استخدام BetVima من تركيا" to "وجود ترجمة تركية أو إمكانية تنزيل التطبيق لا يضمن السماح القانوني بالمراهنة أو إجراء المدفوعات في تركيا. ينبغي مراجعة التشريعات المحلية وشروط الجهات المختصة وتوافر الخدمات قبل التسجيل أو الإيداع. قد تتغير القيود حسب المنتج وطريقة الدفع وموقع المستخدم."),
        "Using BetVima from Afghanistan" to ("استخدام BetVima من أفغانستان" to "وجود واجهة بلغة دَرية أو خدمة قابلة للوصول لا يثبت قانونية المراهنة في أفغانستان. تحقق من الأحكام المحلية وقيود الشبكات والدفع ومزوّدي الخدمة، ولا تعتمد على اللغة أو العلم لتحديد الأهلية. قد لا تتوفر بعض المنتجات أو طرق الدفع."),
        "Using BetVima from Tajikistan" to ("استخدام BetVima من طاجيكستان" to "يجب على المستخدم في طاجيكستان مراجعة الأنظمة المحلية المتعلقة بالألعاب والمدفوعات والإنترنت قبل استخدام الخدمة. الترجمة أو التوفر التقني لا يشكلان تصريحًا قانونيًا أو وعدًا بإمكانية السحب. تظل أهلية الحساب والمنتجات خاضعة للقانون والقيود المطبقة."),
        "Security, support and dispute tracking" to ("الأمان والدعم ومتابعة النزاعات" to "استخدم مركز الدعم لإرسال طلبات خاصة ومتابعة الردود مع الاحتفاظ بمعرّفات المعاملات والرهانات والإيصالات. لا ترفق كلمات المرور أو رموز المصادقة في الرسائل. عند أي حالة مالية غير واضحة، تحقق من السجل أولًا قبل إعادة المحاولة؛ وتظل سجلات الخادم مرجعًا أساسيًا للمراجعة."),
        "Responsible participation and latest information" to ("المشاركة المسؤولة والمعلومات الحديثة" to "الرهان نشاط محفوف بإمكانية خسارة الأموال. ضع حدودًا شخصية للإنفاق والوقت ولا تحاول تعويض الخسائر أو استخدام أموال الاحتياجات الأساسية. يتحكم القانون المحلي وشروط المزوّدين وأحدث السياسات الرسمية في إتاحة الخدمات. راجع المصادر الرسمية واطلب المساعدة إذا أصبحت المراهنة تسبب ضررًا.")
    )
}
